import{c as o,Q as r,j as t,m as a}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"Update Your PHP Version","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/update-php-version.md","filePath":"how-to/update-php-version.md"}'),s={name:"how-to/update-php-version.md"};function n(i,e,p,h,u,d){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="update-your-php-version" tabindex="-1">Update Your PHP Version <a class="header-anchor" href="#update-your-php-version" aria-label="Permalink to &quot;Update Your PHP Version&quot;">​</a></h1><p>PHP is the most popular server-side scripting language, powering millions of websites including yours. If you arrived at this page from a notice in your theme, your server is running an <strong>outdated and unmaintained</strong> version of PHP. This affects your website&#39;s performance, may cause unexpected issues, and exposes you to potential security vulnerabilities.</p><h2 id="what-is-php" tabindex="-1">What is PHP? <a class="header-anchor" href="#what-is-php" aria-label="Permalink to &quot;What is PHP?&quot;">​</a></h2><p>PHP is the scripting language that powers your WordPress website. Like all software, PHP gets updated over time to patch security issues and improve performance. Keeping your PHP version up to date is just as important as keeping WordPress and your themes updated.</p><h2 id="how-to-update-your-php-version" tabindex="-1">How to Update Your PHP Version <a class="header-anchor" href="#how-to-update-your-php-version" aria-label="Permalink to &quot;How to Update Your PHP Version&quot;">​</a></h2><p>In most cases you cannot update PHP yourself — you need to contact your host. The upgrade is a straightforward process that should not impact your website or cost you anything extra. Here is a template you can send to your hosting company:</p><blockquote><p><em>Dear host,</em></p><p><em>I&#39;m running a WordPress website on one of your servers and my WordPress theme recommends using at least PHP 8.0. WordPress lists PHP 8.0+ as the recommended version on their requirements page: <a href="https://wordpress.org/about/requirements/" target="_blank" rel="noreferrer">https://wordpress.org/about/requirements/</a></em></p><p><em>Can you please let me know if my hosting supports PHP 8.0 or higher and how I can upgrade?</em></p><p><em>Looking forward to your reply.</em></p></blockquote><h2 id="my-host-doesn-t-support-php-8-0" tabindex="-1">My Host Doesn&#39;t Support PHP 8.0 <a class="header-anchor" href="#my-host-doesn-t-support-php-8-0" aria-label="Permalink to &quot;My Host Doesn&#39;t Support PHP 8.0&quot;">​</a></h2><p>If your host doesn&#39;t support PHP 8.0 or higher, we recommend switching to a host that does. See our list of <a href="./../general/recommended-web-hosts.html">recommended web hosts</a>. When contacting a new host, always ask which PHP version your website will run on before purchasing.</p><h2 id="more-information" tabindex="-1">More Information <a class="header-anchor" href="#more-information" aria-label="Permalink to &quot;More Information&quot;">​</a></h2><ul><li><a href="http://php.net/eol.php" target="_blank" rel="noreferrer">PHP unsupported versions and end-of-life dates</a></li><li><a href="https://wordpress.org/hosting/" target="_blank" rel="noreferrer">WordPress hosting solutions</a></li><li><a href="http://www.wpupdatephp.com/" target="_blank" rel="noreferrer">WPupdatePHP</a> — a PHP library for plugin developers</li></ul>',11)])])}const P=o(s,[["render",n]]);export{m as __pageData,P as default};
